using System.Windows.Forms;using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Threading.Tasks;
sealed partial class WorkspaceWindow {
 string SharedRoot {get{return Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Studio Suite");}}
 void RegisterWorkscape(){string folder=Path.Combine(SharedRoot,"Workspaces");Directory.CreateDirectory(folder);string file=Path.Combine(folder,Process.GetCurrentProcess().Id+".json");Atomic(file,json.Serialize(new{pid=Process.GetCurrentProcess().Id,id=Path.GetFileName(session),session=session,exe=Application.ExecutablePath}));FormClosed+=(s,e)=>{try{File.Delete(file);}catch{}};try{string connections=Path.Combine(SharedRoot,"connections.json");var all=File.Exists(connections)?json.Deserialize<Dictionary<string,string>>(ReadShared(connections)):new Dictionary<string,string>();all["workspace"]=Application.ExecutablePath;Atomic(connections,json.Serialize(all));}catch{}}
 bool HandoffPath(string path){string resolved=Path.GetFullPath(path),folder=Path.GetFullPath(Path.Combine(SharedRoot,"Handoffs"))+Path.DirectorySeparatorChar;return resolved.StartsWith(folder,StringComparison.OrdinalIgnoreCase)&&File.Exists(resolved);}
 async Task OpenHandoff(string path){try{if(!HandoffPath(path)||new FileInfo(path).Length>180000000)throw new Exception("Choose a supported local studio handoff.");await AcceptHandoff(json.Deserialize<Dictionary<string,object>>(ReadShared(path)));}catch(Exception e){SetStatus("Handoff could not open: "+e.Message);}}
 async Task AcceptHandoff(Dictionary<string,object> data){string target=Convert.ToString(data["target"]),transfer=Convert.ToString(data["path"]);if(!studios.ContainsKey(target)||!HandoffPath(transfer)||Path.GetExtension(transfer)!=".jagotransfer")throw new Exception("The studio transfer is invalid.");object source;if(data.TryGetValue("sourceDocument",out source)&&source!=null){string studio=Convert.ToString(data["sourceStudio"]);if(!studios.ContainsKey(studio)||items.Count>10)throw new Exception("There is not enough room for both projects. Open another Workscape.");string sourceExe=Convert.ToString(data["sourceExe"]);if(File.Exists(sourceExe))ChooseStudio(studio,sourceExe);var from=Add(studio,source);if(from==null)throw new Exception("The source project could not open.");Start(from);}string route=data.ContainsKey("route")?Convert.ToString(data["route"]):"new";var tab=items.Find(t=>t.id==route&&t.studio==target);if(tab==null)tab=Add(target);if(tab==null)throw new Exception("This Workscape has no room for another tab.");tabs.SelectedTab=tab.page;Start(tab);Command(tab,"receive",new Dictionary<string,object>{{"path",transfer}});await SelectTab();if(WindowState==System.Windows.Forms.FormWindowState.Minimized)WindowState=System.Windows.Forms.FormWindowState.Normal;Activate();SetStatus("Transfer opened in "+studios[target]+". Review it before bringing it into the project.");}
}
